        notesCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getDescription().orElse("")));

        table.getColumns().addAll(nameCol, categoryCol, amountCol, intervalCol, monthlyCol, startCol, endCol, notesCol);
        return table;
    }

